CREATE FUNCTION public.erp_create_document(p_company uuid,p_kind text,p_party uuid,p_date date,p_due date,p_currency text,p_rate numeric,p_reference text,p_notes text,p_items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE doc uuid; num text; item jsonb; qty numeric; price numeric; disc numeric; rate numeric; net numeric; tax numeric; st numeric:=0; tx numeric:=0; party_kind text; BEGIN IF NOT public.erp_access(p_company,true) THEN RAISE EXCEPTION 'Company accounting access required'; END IF; IF p_kind NOT IN ('invoice','bill','expense','sales_order','purchase_order') OR p_rate<=0 OR (p_currency='KES' AND p_rate<>1) THEN RAISE EXCEPTION 'Invalid document or exchange rate'; END IF; IF jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'At least one item required'; END IF; IF p_kind<>'expense' THEN SELECT kind INTO party_kind FROM public.erp_parties WHERE id=p_party AND company_id=p_company AND NOT archived; IF party_kind IS NULL OR (p_kind IN ('invoice','sales_order') AND party_kind<>'customer') OR (p_kind IN ('bill','purchase_order') AND party_kind<>'supplier') THEN RAISE EXCEPTION 'Select a valid company customer or supplier'; END IF; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_company::text,0)); num=upper(left(p_kind,3))||'-'||to_char(p_date,'YYYY')||'-'||lpad((SELECT count(*)+1 FROM public.erp_documents WHERE company_id=p_company)::text,6,'0'); INSERT INTO public.erp_documents(company_id,kind,number,party_id,document_date,due_date,currency,exchange_rate,supplier_reference,notes) VALUES(p_company,p_kind,num,p_party,p_date,p_due,p_currency,p_rate,nullif(trim(p_reference),''),p_notes) RETURNING id INTO doc; FOR item IN SELECT * FROM jsonb_array_elements(p_items) LOOP qty=(item->>'quantity')::numeric; price=(item->>'unit_price')::numeric; disc=coalesce((item->>'discount')::numeric,0); IF qty<=0 OR price<0 OR disc<0 OR disc>round(qty*price,2) OR length(trim(item->>'description'))=0 THEN RAISE EXCEPTION 'Invalid item'; END IF; SELECT t.rate INTO rate FROM public.erp_tax_codes t WHERE id=(item->>'tax_code_id')::uuid AND company_id=p_company; IF rate IS NULL THEN RAISE EXCEPTION 'Invalid company tax code'; END IF; net=round(qty*price-disc,2); tax=round(net*rate/100,2); INSERT INTO public.erp_document_items(company_id,document_id,description,quantity,unit,unit_price,discount,tax_code_id,net_amount,tax_amount) VALUES(p_company,doc,item->>'description',qty,coalesce(item->>'unit','Sqm'),price,disc,(item->>'tax_code_id')::uuid,net,tax); st=st+net; tx=tx+tax; END LOOP; IF st+tx<=0 THEN RAISE EXCEPTION 'Document total must be positive'; END IF; UPDATE public.erp_documents SET subtotal=st,tax_amount=tx,total=st+tx WHERE id=doc; INSERT INTO public.erp_audit_events(company_id,action,record_id,detail) VALUES(p_company,'document_created',doc,jsonb_build_object('kind',p_kind,'total',st+tx)); RETURN doc; END $$;
REVOKE ALL ON FUNCTION public.erp_create_document(uuid,text,uuid,date,date,text,numeric,text,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.erp_create_document(uuid,text,uuid,date,date,text,numeric,text,text,jsonb) TO authenticated;
CREATE FUNCTION public.erp_post_document(p_document uuid,p_payment_account uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.erp_documents; j uuid; debit_code text; credit_code text; tax_code text; base_net numeric; base_tax numeric; total numeric; target uuid; BEGIN SELECT * INTO d FROM public.erp_documents WHERE id=p_document FOR UPDATE; IF d.id IS NULL OR NOT public.erp_access(d.company_id,true) THEN RAISE EXCEPTION 'Company accounting access required'; END IF; IF d.status<>'draft' OR d.kind NOT IN ('invoice','bill','expense') THEN RAISE EXCEPTION 'Only draft invoices, bills or expenses can be posted'; END IF; PERFORM public.erp_initialize(d.company_id); base_net=round(d.subtotal*d.exchange_rate,2); base_tax=round(d.tax_amount*d.exchange_rate,2); total=base_net+base_tax; IF d.kind='invoice' THEN debit_code='1100';credit_code='4000';tax_code='2100'; ELSE debit_code=CASE WHEN d.kind='bill' THEN '1200' ELSE '6000' END; credit_code='2000';tax_code='1300'; END IF; IF d.kind='expense' THEN SELECT id INTO target FROM public.erp_accounts WHERE id=p_payment_account AND company_id=d.company_id AND code IN ('1000','1010','1020'); IF target IS NULL THEN RAISE EXCEPTION 'Expense payment account required'; END IF; END IF; INSERT INTO public.erp_journals(company_id,source_document_id,description,journal_date) VALUES(d.company_id,d.id,d.number,d.document_date) RETURNING id INTO j; IF d.kind='invoice' THEN INSERT INTO public.erp_journal_lines(company_id,journal_id,account_id,debit,credit) SELECT d.company_id,j,id,total,0 FROM public.erp_accounts WHERE company_id=d.company_id AND code=debit_code; IF base_net>0 THEN INSERT INTO public.erp_journal_lines(company_id,journal_id,account_id,debit,credit) SELECT d.company_id,j,id,0,base_net FROM public.erp_accounts WHERE company_id=d.company_id AND code=credit_code; END IF; IF base_tax>0 THEN INSERT INTO public.erp_journal_lines(company_id,journal_id,account_id,debit,credit) SELECT d.company_id,j,id,0,base_tax FROM public.erp_accounts WHERE company_id=d.company_id AND code=tax_code; END IF; ELSE IF base_net>0 THEN INSERT INTO public.erp_journal_lines(company_id,journal_id,account_id,debit,credit) SELECT d.company_id,j,id,base_net,0 FROM public.erp_accounts WHERE company_id=d.company_id AND code=debit_code; END IF; IF base_tax>0 THEN INSERT INTO public.erp_journal_lines(company_id,journal_id,account_id,debit,credit) SELECT d.company_id,j,id,base_tax,0 FROM public.erp_accounts WHERE company_id=d.company_id AND code=tax_code; END IF; INSERT INTO public.erp_journal_lines(company_id,journal_id,account_id,debit,credit) SELECT d.company_id,j,id,0,total FROM public.erp_accounts WHERE company_id=d.company_id AND (CASE WHEN d.kind='expense' THEN id=target ELSE code=credit_code END); END IF; UPDATE public.erp_documents SET status='posted',posted_at=now() WHERE id=d.id; INSERT INTO public.erp_audit_events(company_id,action,record_id,detail) VALUES(d.company_id,'document_posted',d.id,jsonb_build_object('journal',j,'base_total',total)); RETURN j; END $$;
REVOKE ALL ON FUNCTION public.erp_post_document(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.erp_post_document(uuid,uuid) TO authenticated;
CREATE FUNCTION public.erp_record_payment(p_document uuid,p_account uuid,p_amount numeric,p_date date,p_reference text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.erp_documents; paid numeric; pay uuid; j uuid; amount_base numeric; BEGIN SELECT * INTO d FROM public.erp_documents WHERE id=p_document FOR UPDATE; IF d.id IS NULL OR NOT public.erp_access(d.company_id,true) THEN RAISE EXCEPTION 'Company accounting access required'; END IF; IF d.status<>'posted' OR d.kind NOT IN ('invoice','bill') OR p_amount<=0 OR round(p_amount,2)<>p_amount THEN RAISE EXCEPTION 'Invalid payment'; END IF; IF NOT EXISTS(SELECT 1 FROM public.erp_accounts WHERE id=p_account AND company_id=d.company_id AND code IN ('1000','1010','1020')) THEN RAISE EXCEPTION 'Invalid payment account'; END IF; IF length(trim(p_reference))=0 THEN RAISE EXCEPTION 'Payment reference required'; END IF; SELECT coalesce(sum(amount),0) INTO paid FROM public.erp_payments WHERE document_id=d.id; IF paid+p_amount>d.total THEN RAISE EXCEPTION 'Payment exceeds outstanding balance'; END IF; INSERT INTO public.erp_payments(company_id,document_id,account_id,amount,payment_date,reference) VALUES(d.company_id,d.id,p_account,p_amount,p_date,trim(p_reference)) RETURNING id INTO pay; amount_base=round((paid+p_amount)*d.exchange_rate,2)-round(paid*d.exchange_rate,2); INSERT INTO public.erp_journals(company_id,source_payment_id,description,journal_date) VALUES(d.company_id,pay,'Payment '||p_reference,p_date) RETURNING id INTO j; INSERT INTO public.erp_journal_lines(company_id,journal_id,account_id,debit,credit) VALUES(d.company_id,j,p_account,CASE WHEN d.kind='invoice' THEN amount_base ELSE 0 END,CASE WHEN d.kind='bill' THEN amount_base ELSE 0 END); INSERT INTO public.erp_journal_lines(company_id,journal_id,account_id,debit,credit) SELECT d.company_id,j,id,CASE WHEN d.kind='bill' THEN amount_base ELSE 0 END,CASE WHEN d.kind='invoice' THEN amount_base ELSE 0 END FROM public.erp_accounts WHERE company_id=d.company_id AND code=CASE WHEN d.kind='invoice' THEN '1100' ELSE '2000' END; INSERT INTO public.erp_audit_events(company_id,action,record_id,detail) VALUES(d.company_id,'payment_recorded',pay,jsonb_build_object('document',d.id,'amount',p_amount)); RETURN pay; END $$;
REVOKE ALL ON FUNCTION public.erp_record_payment(uuid,uuid,numeric,date,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.erp_record_payment(uuid,uuid,numeric,date,text) TO authenticated;
CREATE FUNCTION public.erp_party_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.company_id<>OLD.company_id THEN RAISE EXCEPTION 'Company ownership cannot change'; END IF; INSERT INTO public.erp_audit_events(company_id,action,record_id,detail) VALUES(NEW.company_id,'party_'||lower(TG_OP),NEW.id,jsonb_build_object('new',to_jsonb(NEW),'old',CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END)); RETURN NEW; END $$;
CREATE TRIGGER erp_party_audit AFTER INSERT OR UPDATE ON public.erp_parties FOR EACH ROW EXECUTE FUNCTION public.erp_party_audit();